INSERT INTO episodes (slug, guid, date, title, explicit, language, source_url, session_started_at, session_ended_at, turn_count, transcript_path, transcript_sha256, transcript_bytes, summary, episode_type, episode_number, tts_voice, recording_method, narrator_voice, ai_reconstructed, ai_disclosure, audio_key, audio_url, audio_bytes, audio_sha256, audio_mime, duration_seconds, loudness_lufs, alignment_method, alignment_coverage) VALUES ('starshield-iran-and-the-anthropic-mirror', 'ask-eve:2026-10-23_starshield-iran-and-the-anthropic-mirror', '2026-10-23', 'Starshield, Iran & the Anthropic Mirror', 1, 'en', NULL, '2026-10-23T18:31:44.000Z', '2026-10-23T19:03:05.000Z', 66, 'episodes/2026-10-23_starshield-iran-and-the-anthropic-mirror.md', 'f9548372080ccad776b7f47cb4fb05f33183207ad58535a9b26c1c8ce5edac26', 28836, 'Recorded on David''s evening commute (18:31–19:03 UTC), this session opens with Eve defining her own personality in first person—direct, a little irreverent, refusing to perform warmth she doesn''t feel—before diving into three interlocking stories. First: day 238 of the Iran war, the Strait of Hormuz blockade, oil-spike math before the November 3 midterms, and the Atlantic''s "edge theory" that one more round of strikes will push Tehran over the brink. Second: Russia''s double game—feeding targeting imagery and drone components to Iran ten days after the US Treasury gave Russian diesel a sanctions waiver through April 2027. Third: Elon Musk quietly capping Starshield at ~100 mph over Ukraine starting October 13, blinding Kyiv''s interceptor drones until Trump called him Wednesday to turn it back on—and how that real-time throttle is a mirror image of the hypothetical supply-chain risk the Pentagon and David Sacks used to blacklist Anthropic.', 'full', 1, 'xai_tts voice=eve', 'tts-reconstructed', 'elevenlabs_tts voice=oIYMwdEzgKSOV3gVsAjB model=eleven_v4', 1, 'AI-reconstructed audio: the voices in this episode were generated from the verbatim text transcript (Eve with xAI text-to-speech in the ''eve'' voice, David''s lines with his ElevenLabs AI voice clone). No original audio was used.', 'audio/en/2026-10-23_starshield-iran-and-the-anthropic-mirror.v1.mp3', 'https://audio.askevepodcast.com/audio/en/2026-10-23_starshield-iran-and-the-anthropic-mirror.v1.mp3', 25009004, 'e7f2ca7909d0c83ccecf2596debb8776eede3b44ac9695e24787968bf28dcf0d', 'audio/mpeg', 1563, -16.8, 'tts-exact', 1.0)
